[{"order":1,"type":"heading","text":"Unit Testing & Integration Testing in Unity (Test Framework)"},{"order":2,"type":"paragraph","text":"Automated testing is a cornerstone of professional game development. Unity provides the Unity Test Framework (UTF), built on top of NUnit, allowing developers to write and execute both EditMode and PlayMode tests to ensure code reliability and catch regressions early."},{"order":3,"type":"subheading","text":"1. Setting Up the Unity Test Framework"},{"order":4,"type":"paragraph","text":"To get started, open the Unity Package Manager via Window > Package Manager, locate the "Test Framework" package, and ensure it is installed in your project. Next, open the Test Runner window via Window > General > Test Runner to view and execute your tests."},{"order":5,"type":"subheading","text":"2. Writing a Unit Test (EditMode)"},{"order":6,"type":"paragraph","text":"Unit tests focus on individual classes and methods without requiring the Unity engine to run a scene. They execute quickly and are ideal for testing pure logic, mathematical calculations, and state machines."},{"order":7,"type":"code","text":"using NUnit.Framework;

public class MathUtilsTests
{
    [Test]
    public void Add_ReturnsCorrectSum()
    {
        int a = 5;
        int b = 10;
        int result = a + b;
        Assert.AreEqual(15, result);
    }
}"},{"order":8,"type":"subheading","text":"3. Writing an Integration Test (PlayMode)"},{"order":9,"type":"paragraph","text":"Integration tests run in the Unity player loop, allowing you to test interactions between multiple systems, GameObjects, components, and asynchronous operations (using Coroutines)."},{"order":10,"type":"code","text":"using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;

public class PlayerIntegrationTests
{
    [UnityTest]
    public IEnumerator Player_MovesForward_OverTime()
    {
        GameObject player = new GameObject("Player");
        var rb = player.AddComponent<Rigidbody>();

        rb.velocity = Vector3.forward * 5f;

        yield return new WaitForSeconds(1f);

        Assert.Greater(player.transform.position.z, 0f);
        Object.Destroy(player);
    }
}"},{"order":11,"type":"subheading","text":"Best Practices for Unity Testing"},{"order":12,"type":"bullet_point","text":"Keep EditMode tests isolated: Do not instantiate heavy engine objects unless necessary."},{"order":13,"type":"bullet_point","text":"Clean up after PlayMode tests: Always destroy instantiated GameObjects using Object.Destroy to avoid memory leaks between test runs."},{"order":14,"type":"bullet_point","text":"Use Setup and Teardown attributes ([SetUp] and [TearDown]) to configure shared test states cleanly."}]
